  /* 背景色：クリーンな白ベースに微かな藍の色相を保持 */
  --bg-main: #f7f9fc;
  --bg-card: #ffffff;
  --bg-sidebar: #f3f6fb;

  /* ボーダー：Salesforceの洗練された細い線 */
  --border: #d3dce6;
  --border-width: 1px;

  /* テキスト：高コントラストの濃紺 */
  --text: #16325c;
  --text-muted: #576d7b;

  /* トップバー：Salesforce標準の濃紺ヘッダー */
  --top-bar-bg: #0b5394;
  --top-bar-border: #054098;
  --top-bar-text: #ffffff;

  /* タイポグラフィ：Salesforceの標準フォントスタック */
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Salesforce Sans', sans-serif;

  /* 角丸：Salesforceの控えめで洗練された角丸 */
  --radius-card: 4px;
  --radius-control: 3px;

  /* シャドウ：Salesforceの微妙で奥行きのある影 */
  --shadow-card: 0 2px 4px rgba(11, 83, 148, 0.08), 0 1px 2px rgba(11, 83, 148, 0.04);

  /* コントロール寸法：Salesforceの標準的なコンパクト設計 */
  --control-height: 32px;
  --space-unit: 8px;

  /* アニメーション：Salesforceの洗練された動き */
  --motion-duration: 200ms;

  /* 質感：Salesforceの企業向けシステムの信頼感を表現する微細なテクスチャ */
  /* 薄い格子パターンで、データ管理システムの秩序感を表現 */
  --surface-texture: linear-gradient(90deg, rgba(0, 112, 210, 0.02) 1px, transparent 1px),
                     linear-gradient(rgba(0, 112, 210, 0.02) 1px, transparent 1px);
  --surface-texture-size: 16px 16px;
  --surface-texture-position: 0 0;
}
