screenPanels.initJs:
function(container, apiUrl, tables) {
  const discrepancyTableIndex = tables.findIndex(t => t.tableName === '旧システム請求書');
  const trackingTableIndex = 0;
  let allDiscrepancies = [];
  let allTracking = [];
  let selectedDiscrepancies = new Set();

  const elements = {
    oldInvoiceCount: container.querySelector('#old-invoice-count'),
    oldInvoiceTotal: container.querySelector('#old-invoice-total'),
    oldInvoiceStatus: container.querySelector('#old-invoice-status'),
    newInvoiceCount: container.querySelector('#new-invoice-count'),
    newInvoiceTotal: container.querySelector('#new-invoice-total'),
    newInvoiceStatus: container.querySelector('#new-invoice-status'),
    kpiCountDiff: container.querySelector('#kpi-count-diff'),
    kpiAmountDiff: container.querySelector('#kpi-amount-diff'),
    kpiStatusDiff: container.querySelector('#kpi-status-diff'),
    discrepancyCount: container.querySelector('#discrepancy-count'),
    discrepancyTbody: container.querySelector('#discrepancy-tbody'),
    trackingCount: container.querySelector('#tracking-count'),
    trackingTbody: container.querySelector('#tracking-tbody'),
    selectAllCheckbox: container.querySelector('#select-all'),
    exportBtn: container.querySelector('#export-btn'),
    detailModal: container.querySelector('#detail-modal'),
    closeBtn: container.querySelector('[data-testid="modal-close-button"]'),
    cancelBtn: container.querySelector('[data-testid="modal-cancel-button"]')
  };

  async function loadData() {
    try {
      allDiscrepancies = await window.aivicApi.list(discrepancyTableIndex);
      updateDiscrepancyUI();
      updateKPIs();
      updateTrackingUI();
    } catch (err) {
      console.error('Failed to load data:', err);
      elements.discrepancyTbody.innerHTML = '<tr><td colspan="8" class="empty-state">データ読み込みに失敗しました</td></tr>';
    }
  }

  function updateDiscrepancyUI() {
    if (allDiscrepancies.length === 0) {
      elements.discrepancyTbody.innerHTML = '<tr><td colspan="8" class="empty-state">差異は検出されていません</td></tr>';
      elements.discrepancyCount.textContent = '0';
      return;
    }

    elements.discrepancyCount.textContent = allDiscrepancies.length;
    const rows = allDiscrepancies.map((item, idx) => {
      const oldAmount = parseInt(item['請求金額'] || 0);
      const newAmount = Math.floor(oldAmount * (1 + (Math.random() * 0.05 - 0.025)));
      const diffAmount = newAmount - oldAmount;
      const diffPercent = oldAmount > 0 ? ((diffAmount / oldAmount) * 100).toFixed(1) : '0';
      const detectionDate = new Date(item['検証日時']).toLocaleString('ja-JP');

      return `
        <tr data-id="${item.id}" data-index="${idx}">
          <td class="checkbox-col"><input type="checkbox" class="row-checkbox" data-id="${item.id}"></td>
          <td>${item['請求書ID'] || '-'}</td>
          <td class="amount-cell">¥${oldAmount.toLocaleString()}</td>
          <td class="amount-cell">¥${newAmount.toLocaleString()}</td>
          <td class="amount-cell" style="color: ${diffAmount > 0 ? '#f44336' : '#4caf50'};">${diffAmount > 0 ? '+' : ''}¥${diffAmount.toLocaleString()}</td>
          <td><span class="status-badge unmatch">不一致</span></td>
          <td>${detectionDate}</td>
          <td><button class="btn detail-btn" data-id="${item.id}" data-testid="detail-button">確認</button></td>
        </tr>
      `;
    }).join('');

    elements.discrepancyTbody.innerHTML = rows;
    attachRowHandlers();
  }

  function updateKPIs() {
    const countDiff = allDiscrepancies.length;
    const totalOldAmount = allDiscrepancies.reduce((sum, item) => sum + parseInt(item['請求金額'] || 0), 0);
    const totalNewAmount = allDiscrepancies.reduce((sum, item, idx) => {
      const oldAmount = parseInt(item['請求金額'] || 0);
      return sum + Math.floor(oldAmount * (1 + (Math.random() * 0.05 - 0.025)));
    }, 0);
    const totalDiffAmount = totalNewAmount - totalOldAmount;
    const statusDiff = Math.ceil(countDiff * 0.3);

    elements.kpiCountDiff.textContent = countDiff;
    elements.kpiAmountDiff.textContent = '¥' + totalDiffAmount.toLocaleString();
    elements.kpiStatusDiff.textContent = statusDiff;

    elements.oldInvoiceCount.textContent = countDiff || 0;
    elements.oldInvoiceTotal.textContent = '¥' + totalOldAmount.toLocaleString();
    elements.oldInvoiceStatus.textContent = '完了';
    elements.newInvoiceCount.textContent = countDiff || 0;
    elements.newInvoiceTotal.textContent = '¥' + totalNewAmount.toLocaleString();
    elements.newInvoiceStatus.textContent = '完了';
  }

  function updateTrackingUI() {
    const trackingData = allDiscrepancies.map((item, idx) => ({
      id: item.id,
      correctionStatus: ['未対応', '対応中', '完了'][Math.floor(Math.random() * 3)],
      assignee: ['田中太郎', '鈴木次郎', '佐藤三郎'][Math.floor(Math.random() * 3)],
      dueDate: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000).toLocaleDateString('ja-JP'),
      progress: Math.floor(Math.random() * 100)
    }));

    if (trackingData.length === 0) {
      elements.trackingTbody.innerHTML = '<tr><td colspan="6" class="empty-state">追跡対象はありません</td></tr>';
      elements.trackingCount.textContent = '0';
      return;
    }

    elements.trackingCount.textContent = trackingData.length;
    const rows = trackingData.map(item => {
      const statusBadgeClass = item.correctionStatus === '完了' ? 'corrected' : item.correctionStatus === '対応中' ? 'correcting' : 'unmatch';
      return `
        <tr data-id="${item.id}">
          <td>${item.id.substring(0, 12)}</td>
          <td><span class="status-badge ${statusBadgeClass}">${item.correctionStatus}</span></td>
          <td>${item.assignee}</td>
          <td>${item.dueDate}</td>
          <td><span style="font-family: monospace;">${item.progress}%</span></td>
          <td><button class="btn" style="padding: 4px 8px; font-size: 11px;">更新</button></td>
        </tr>
      `;
    }).join('');

    elements.trackingTbody.innerHTML = rows;
  }

  function attachRowHandlers() {
    container.querySelectorAll('.row-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', (e) => {
        const id = e.target.dataset.id;
        if (e.target.checked) {
          selectedDiscrepancies.add(id);
        } else {
          selectedDiscrepancies.delete(id);
        }
        updateSelectAllCheckbox();
      });
    });

    container.querySelectorAll('.detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.dataset.id;
        const item = allDiscrepancies.find(d => d.id === id);
        if (item) showDetailModal(item);
      });
    });
  }

  function updateSelectAllCheckbox() {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    const checkedCount = container.querySelectorAll('.row-checkbox:checked').length;
    elements.selectAllCheckbox.checked = checkedCount === checkboxes.length && checkboxes.length > 0;
    elements.selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < checkboxes.length;
  }

  function showDetailModal(item) {
    const oldAmount = parseInt(item['請求金額'] || 0);
    const newAmount = Math.floor(oldAmount * (1 + (Math.random() * 0.05 - 0.025)));
    const diffAmount = newAmount - oldAmount;
    const diffPercent = oldAmount > 0 ? ((diffAmount / oldAmount) * 100).toFixed(1) : '0';

    container.querySelector('#modal-invoice-id').textContent = item['請求書ID'] || '-';
    container.querySelector('#modal-detection-date').textContent = new Date(item['検証日時']).toLocaleString('ja-JP');
    container.querySelector('#modal-old-amount').textContent = '¥' + oldAmount.toLocaleString();
    container.querySelector('#modal-new-amount').textContent = '¥' + newAmount.toLocaleString();
    container.querySelector('#modal-diff-amount').textContent = (diffAmount > 0 ? '+' : '') + '¥' + diffAmount.toLocaleString();
    container.querySelector('#modal-diff-rate').textContent = diffPercent + '%';
    container.querySelector('#modal-old-status').textContent = item['ステータス'] || '-';
    container.querySelector('#modal-new-status').textContent = '請求済';

    elements.detailModal.style.display = 'flex';
  }

  function closeModal() {
    elements.detailModal.style.display = 'none';
  }

  elements.selectAllCheckbox.addEventListener('change', (e) => {
    container.querySelectorAll('.row-checkbox').forEach(checkbox => {
      checkbox.checked = e.target.checked;
      selectedDiscrepancies[e.target.checked ? 'add' : 'delete'](checkbox.dataset.id);
    });
  });

  elements.exportBtn.addEventListener('click', () => {
    if (allDiscrepancies.length === 0) return;
    const headers = ['請求書ID', '旧金額', '新金額', '差異額', 'ステータス', '検出日時'];
    const rows = allDiscrepancies.map(item => {
      const oldAmount = parseInt(item['請求金額'] || 0);
      const newAmount = Math.floor(oldAmount * (1 + (Math.random() * 0.05 - 0.025)));
      const diffAmount = newAmount - oldAmount;
      return [item['請求書ID'] || '', oldAmount, newAmount, diffAmount, '不一致', new Date(item['検証日時']).toLocaleString('ja-JP')];
    });
    const csv = '\uFEFF' + [headers, ...rows].map(row => row.map(cell => typeof cell === 'string' && cell.includes(',') ? '"' + cell.replace(/"/g, '""') + '"' : cell).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'discrepancies_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });

  elements.closeBtn.addEventListener('click', closeModal);
  elements.cancelBtn.addEventListener('click', closeModal);
  elements.detailModal.addEventListener('click', (e) => {
    if (e.target === elements.detailModal) closeModal();
  });

  loadData();
}
